<?php
/** Procurement answers on a system budget — included by system_budget.php ($B, $CUR, $id, $self, $ed, $isRev, $tpl, $cur).   GAS-CP-R97-049 */
$pSt = sbp_state($CUR); $pRows = array_values(array_filter($B['parts'], fn($p) => !empty($p['proc_at']) || ($p['lead_weeks'] ?? null) !== null || trim((string)($p['proc_note'] ?? '')) !== '' || trim((string)($p['alt_descr'] ?? '')) !== ''));
$pOpen = count(sbp_open_lines($B)); $pMax = sbp_lead_max($B);
?>
<div class="card" id="procurement">
  <div class="card-head"><h2>💶 <?= tt('sbp.card') ?> <?= sbp_pill($CUR) ?><?php if ($pMax !== null): ?> <span class="hint"><?= e(t('sbp.longest', ['w' => sbp_weeks($pMax)])) ?></span><?php endif; ?></h2>
    <div class="btn-row"><?php if ($ed && !$isRev): if ($pSt === 'requested'): ?>
      <form method="post" action="<?= $self ?>" class="inline" data-lock><?= csrf_field() ?><input type="hidden" name="action" value="sbp_recall"><input type="hidden" name="id" value="<?= $id ?>"><button class="btn btn--sm" type="submit">↩ <?= tt('sbp.recall') ?></button></form>
      <?php elseif (array_filter($B['parts'], 'sbp_counts')): ?>
      <form method="post" action="<?= $self ?>" class="inline" data-lock style="display:inline-flex;gap:6px;align-items:center;"><?= csrf_field() ?><input type="hidden" name="action" value="sbp_request"><input type="hidden" name="id" value="<?= $id ?>"><input name="note" maxlength="300" placeholder="<?= tt('sbp.note_ph') ?>" style="min-width:240px;"><button class="btn btn--gold btn--sm" type="submit">➜ <?= tt($pSt === 'done' ? 'sbp.send_again' : 'sbp.send') ?></button></form>
      <?php endif; endif; ?><?php if (sbp_can() && $pSt === 'requested' && !$isRev): ?><a class="btn btn--ghost btn--sm" href="<?= url('system_budget_proc', ['id' => $id]) ?>">✎ <?= tt('sbp.open_form') ?></a><?php endif; ?></div></div>
  <p class="hint" style="margin:0 0 8px;"><?php if ($pSt === 'requested'): ?><?= e(t('sbp.info_requested', ['d' => fmt_datetime((string)$CUR['proc_req_at'])])) ?><?= trim((string)($CUR['proc_note'] ?? '')) !== '' ? ' — ' . e((string)$CUR['proc_note']) : '' ?><?php elseif ($pSt === 'done'): ?><?= e(t('sbp.info_done', ['d' => fmt_datetime((string)$CUR['proc_done_at'])])) ?><?= $pOpen ? ' ' . e(t('sbp.info_open', ['n' => $pOpen])) : '' ?><?php else: ?><?= tt(sbp_required() ? 'sbp.info_none_req' : 'sbp.info_none') ?><?php endif; ?></p>
  <?php if ($pRows): ?><div class="table-scroll"><table class="tbl tbl--compact"><thead><tr><th><?= tt('th.code') ?></th><th style="min-width:220px;"><?= tt('sb.p_descr') ?></th><th class="num"><?= tt('sb.qty') ?></th><th class="num"><?= tt('sbp.c_price') ?></th><th class="num"><?= tt('sbp.c_lead') ?></th><th><?= tt('sbp.c_supplier') ?></th><th><?= tt('sbp.c_note') ?></th><th style="min-width:200px;"><?= tt('sbp.c_alt') ?></th><th></th></tr></thead><tbody>
  <?php foreach ($pRows as $p): $chg = ($p['proc_cost'] ?? null) !== null && abs((float)$p['proc_cost'] - (float)$p['unit_cost']) > 0.0049; ?><tr>
    <td class="mono"><?= e((string)$p['code']) ?></td><td><?= e(mb_substr((string)$p['descr'], 0, 120)) ?></td><td class="num"><?= sb_h((float)$p['qty']) ?> <?= e((string)$p['unit']) ?></td>
    <td class="num"><?= ($p['proc_cost'] ?? null) !== null ? sbc_m((float)$p['proc_cost']) : '—' ?><?= $chg ? '<br>' . pill('gold', t('sbp.changed', ['c' => sbc_m((float)$p['unit_cost'])])) : '' ?></td>
    <td class="num"><?= ($p['lead_weeks'] ?? null) !== null ? e(sbp_weeks((float)$p['lead_weeks'])) : '—' ?></td><td><?= e((string)($p['proc_supplier'] ?? '')) ?></td><td class="hint"><?= e((string)($p['proc_note'] ?? '')) ?></td>
    <td><?php if (trim((string)($p['alt_descr'] ?? '')) !== ''): ?><?= e((string)$p['alt_descr']) ?><br><span class="hint"><?= ($p['alt_cost'] ?? null) !== null ? sbc_m((float)$p['alt_cost']) . ' ' . e($cur) : '' ?><?= ($p['alt_lead_weeks'] ?? null) !== null ? ' · ' . e(t('sbp.weeks', ['w' => sbp_weeks((float)$p['alt_lead_weeks'])])) : '' ?></span><?php endif; ?></td>
    <td><?php if ($ed && !$isRev && $pSt !== 'requested' && trim((string)($p['alt_descr'] ?? '')) !== ''): ?><form method="post" action="<?= $self ?>" class="inline" data-lock data-confirm="<?= tt('sbp.alt_confirm') ?>"><?= csrf_field() ?><input type="hidden" name="action" value="sbp_use_alt"><input type="hidden" name="id" value="<?= $id ?>"><input type="hidden" name="part" value="<?= (int)$p['id'] ?>"><button class="btn btn--ghost btn--sm" type="submit">⇄ <?= tt('sbp.alt_use') ?></button></form><?php endif; ?></td></tr><?php endforeach; ?>
  </tbody></table></div><?php endif; ?>
</div>
